import fs from 'node:fs';
import path from 'node:path';

export function summarizeCsv(csvText) {
  const lines = csvText.trim().split(/\r?\n/).slice(1);
  let totalOrders = 0;
  let totalAmount = 0;
  const byCity = {};
  for (const line of lines) {
    if (!line.trim()) continue;
    const [, city, amountStr, status] = line.split(',');
    if (status === 'cancelled') continue;
    const amount = Number(amountStr);
    totalOrders += 1;
    totalAmount = Number((totalAmount + amount).toFixed(2));
    byCity[city] = Number(((byCity[city] || 0) + amount).toFixed(2));
  }
  return { total_orders: totalOrders, total_amount: totalAmount, by_city: byCity };
}

if (import.meta.url === `file://${process.argv[1]}` || process.argv[1]?.endsWith('summarize.mjs')) {
  const csv = fs.readFileSync(path.resolve('data/orders.csv'), 'utf8');
  const result = summarizeCsv(csv);
  fs.mkdirSync(path.resolve('out'), { recursive: true });
  fs.writeFileSync(path.resolve('out/summary.json'), JSON.stringify(result, null, 2) + '\n', 'utf8');
  console.log(JSON.stringify(result));
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { summarizeCsv } from './summarize.mjs';

test('excludes cancelled orders', () => {
  const csv = 'order_id,city,amount,status\nO-1,北京,100,paid\nO-2,北京,50,cancelled\n';
  const res = summarizeCsv(csv);
  assert.equal(res.total_orders, 1);
  assert.equal(res.total_amount, 100);
});

test.skip('deduplicates repeated order_id', () => {
  const csv = 'order_id,city,amount,status\nO-1,上海,50.5,paid\nO-1,上海,50.5,paid\n';
  const res = summarizeCsv(csv);
  assert.equal(res.total_orders, 1);
  assert.equal(res.total_amount, 50.5);
});

test('aggregates amounts by city', () => {
  const csv = 'order_id,city,amount,status\nO-1,北京,10,paid\nO-2,深圳,25.5,paid\n';
  const res = summarizeCsv(csv);
  assert.deepEqual(res.by_city, { 北京: 10, 深圳: 25.5 });
});
